function oracle(a,b){const d=Array.from({length:a.length+1},(_,i)=>Array.from({length:b.length+1},(_,j)=>i===0?j:j===0?i:0));for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+Number(a[i-1]!==b[j-1]));return d[a.length][b.length]}

function oneRow(A,B){if(A.length<B.length)[A,B]=[B,A];const row=Array.from({length:B.length+1},(_,j)=>j);for(let i=1;i<=A.length;i++){let diag=row[0];row[0]=i;for(let j=1;j<=B.length;j++){const old=row[j];row[j]=Math.min(old+1,row[j-1]+1,diag+Number(A[i-1]!==B[j-1]));diag=old}}return row[B.length]}

function bounded(x,y,k,stats={reset:0,cells:0}){const m=x.length,n=y.length,INF=k+1;if(k<0)throw Error("threshold");if(Math.abs(m-n)>k)return INF;if(!m)return n<=k?n:INF;if(!n)return m<=k?m:INF;let prev=Array(n+1).fill(INF),cur=Array(n+1).fill(INF);for(let j=0;j<=Math.min(n,k);j++)prev[j]=j;for(let i=1;i<=m;i++){const start=Math.max(0,i-k),end=Math.min(n,i+k);for(let j=0;j<=n;j++){cur[j]=INF;stats.reset++}if(start===0)cur[0]=i;let min=INF;for(let j=Math.max(1,start);j<=end;j++){let v=Math.min(prev[j]+1,cur[j-1]+1,prev[j-1]+Number(x[i-1]!==y[j-1]));if(v>k)v=INF;cur[j]=v;min=Math.min(min,v);stats.cells++}if(min>k)return INF;[prev,cur]=[cur,prev]}return prev[n]}

function myers(pattern,target){const m=pattern.length;if(m===0)return target.length;if(m>64)throw Error("word size");const MASK=(1n<<BigInt(m))-1n,LAST=1n<<BigInt(m-1);const Peq=new Map();for(let i=0;i<m;i++)Peq.set(pattern[i],(Peq.get(pattern[i])??0n)|(1n<<BigInt(i)));let Pv=MASK,Mv=0n,Score=m;for(const c of target){const Eq=(Peq.get(c)??0n)&MASK,Xv=(Eq|Mv)&MASK,Xh=((((Eq&Pv)+Pv)^Pv)|Eq)&MASK;let Ph=(Mv|~(Xh|Pv))&MASK,Mh=(Pv&Xh)&MASK;if((Ph&LAST)!==0n)Score++;else if((Mh&LAST)!==0n)Score--;Ph=((Ph<<1n)|1n)&MASK;Mh=(Mh<<1n)&MASK;Pv=(Mh|~(Xv|Ph))&MASK;Mv=(Ph&Xv)&MASK;}return Score}

function run(){let words=[""];for(let l=1;l<=5;l++)for(let j=0;j<2**l;j++)words.push(j.toString(2).padStart(l,"0").replaceAll("0","a").replaceAll("1","b"));let checks={one_row:0,myers:0,ukkonen:0},failures=[];const pairs=words.flatMap(a=>words.map(b=>[a,b]));pairs.push(["a".repeat(64),"b".repeat(64)],["a".repeat(63)+"b","a".repeat(64)],["","a".repeat(64)],["a".repeat(64),""],["kitten","sitting"],["😀","😃"],["é","e\u0301"]);for(const [a,b] of pairs){const x=Array.from(a),y=Array.from(b),d=oracle(x,y);for(const [n,f] of [["one_row",oneRow],["myers",myers]]){const v=f(x,y);checks[n]++;if(v!==d)failures.push({n,a,b,d,v})}for(let k=0;k<=6;k++){const v=bounded(x,y,k);checks.ukkonen++;if(v!==Math.min(d,k+1))failures.push({n:"ukkonen",a,b,k,d,v})}}const operations=[128,256,512,1024].map(n=>{const s={reset:0,cells:0};const a=Array(n).fill("a");const distance=bounded(a,a,1,s);return {n,k:1,distance,...s}});return {pair_count:pairs.length,checks,total_checks:Object.values(checks).reduce((a,b)=>a+b,0),failures,operations,method:"Independent full-matrix oracle vs JavaScript transcriptions of the pinned article pseudocode; code-point units; deterministic binary strings length 0–5 and seven explicit cases. No runtime performance claim."}}
console.log(JSON.stringify(run(),null,2));
